#!/usr/bin/env python3
"""
Round 134b (culprits-tiles-more), 2 October 2026.

glw_relief.py: adds glw_all, every farm animal together (the six FAO GLW4
grids added, each animal counted as one), for the map's All choice.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/glw_relief.py': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round134b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round134b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
